-- Curated exercise catalogue.
--
-- Repeatable: ids are derived from the slug, so re-running this file (or applying it to a new
-- environment) always yields the same canonical exercise ids. Updating a row here renames it
-- everywhere without touching anyone's history, because history references the id.
-- Genuinely different variations (barbell vs dumbbell vs machine, different movements) are
-- separate exercises and are never merged.

insert into public.exercises (id, slug, name, primary_muscle, equipment, tracking_mode, aliases)
select md5('splitmate.catalogue:' || v.slug)::uuid, v.slug, v.name, v.muscle, v.equipment, v.mode, v.aliases
from (values
  ('barbell-bench-press', 'Barbell Bench Press', 'chest', 'barbell', 'weight_reps', array['bench press', 'flat bench']::text[]),
  ('incline-barbell-bench-press', 'Incline Barbell Bench Press', 'chest', 'barbell', 'weight_reps', array['incline press', 'incline bench']::text[]),
  ('decline-barbell-bench-press', 'Decline Barbell Bench Press', 'chest', 'barbell', 'weight_reps', array['decline bench']::text[]),
  ('dumbbell-bench-press', 'Dumbbell Bench Press', 'chest', 'dumbbell', 'weight_reps', array['db bench', 'flat dumbbell press']::text[]),
  ('incline-dumbbell-press', 'Incline Dumbbell Press', 'chest', 'dumbbell', 'weight_reps', array['incline db press', 'incline press']::text[]),
