on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  primary_muscle = excluded.primary_muscle,
  equipment = excluded.equipment,
  tracking_mode = excluded.tracking_mode,
  aliases = excluded.aliases,
  updated_at = now();
